for name,desc in [('ALTRENO','Tretinoin lotion.'),('ARAZLO','Tazarotene lotion.'),('BRYHALI','Halobetasol-propionate lotion.'),('CABTREO','Clindamycin/adapalene/benzoyl-peroxide gel.'),('CLINDAGEL','Clindamycin-phosphate gel.'),('DUOBRII','Halobetasol-propionate/tazarotene lotion.'),('ELIDEL','Pimecrolimus cream.'),('JUBLIA','Efinaconazole topical solution.'),('LUZU','Luliconazole cream.'),('NORITATE','Metronidazole cream.'),('ONEXTON','Clindamycin-phosphate/benzoyl-peroxide gel.'),('RENOVA','Tretinoin cream.'),('Retin-A cream','Tretinoin cream formulation.'),('Retin-A Micro','Tretinoin microsphere-gel formulation.'),('SILIQ','Brodalumab injection.'),('TARGRETIN capsules','Bexarotene oral formulation.'),('TARGRETIN gel','Bexarotene topical formulation.'),('XERESE','Acyclovir/hydrocortisone cream.'),('ZIANA','Clindamycin-phosphate/tretinoin gel.'),('ZOVIRAX cream','Acyclovir cream formulation.'),('ZYCLARA','Imiquimod cream.')]:drug(name,desc,O)
