for name in ['OSSIX BONE','OSSIX PLUS','OSSIX VOLUMAX','OSSIX GRAFT']:drug(name,'Named dental-regeneration product.',D,attributes={'relationship_note':'marketed via OraPharma partnership with Datum Dental; original developer not attributed'})
for name,desc in [('Thermage FLX','Radiofrequency dermatologic treatment system.'),('Fraxel FTX','Fractionated-laser dermatologic treatment system.'),('Clear + Brilliant Touch','Fractionated-laser skin-resurfacing system.'),('VASERlipo','Ultrasonic liposuction system family.')]:drug(name,desc,T,evidence=[T,P] if name!='VASERlipo' else [T])
